import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.vLhlLNVn.js";const b=JSON.parse('{"title":"Wie schalte ich das ESPHome-Dashboard ein und öffne es?","description":"","frontmatter":{"order":4,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/01.erste-schritte/04.dashboard-einschalten.md"},"headers":[],"relativePath":"de/adapter/esphome/erste-schritte/dashboard-einschalten.md","filePath":"de/adapter/esphome/erste-schritte/dashboard-einschalten.md","lastUpdated":1795388431000}'),d={name:"de/adapter/esphome/erste-schritte/dashboard-einschalten.md"};function s(i,e,o,h,c,l){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="wie-schalte-ich-das-esphome-dashboard-ein-und-offne-es" tabindex="-1">Wie schalte ich das ESPHome-Dashboard ein und öffne es? <a class="header-anchor" href="#wie-schalte-ich-das-esphome-dashboard-ein-und-offne-es" aria-label="Permalink to &quot;Wie schalte ich das ESPHome-Dashboard ein und öffne es?&quot;">​</a></h1><p><a id="dashboard-tab-not-open-localhost"></a></p><h2 id="warum-offnet-sich-der-dashboard-tab-nicht-localhost-verweigert-die-verbindung" tabindex="-1">Warum öffnet sich der Dashboard-Tab nicht (&quot;localhost verweigert die Verbindung&quot;)? <a class="header-anchor" href="#warum-offnet-sich-der-dashboard-tab-nicht-localhost-verweigert-die-verbindung" aria-label="Permalink to &quot;Warum öffnet sich der Dashboard-Tab nicht (&quot;localhost verweigert die Verbindung&quot;)?&quot;">​</a></h2><p><strong>Kurz:</strong> Trag bei „IP-Adresse, unter der ESPHome Dashboard zur Integration in ioBroker Admin ausgeführt wird“ die IP-Adresse deines ioBroker-Rechners ein, ohne Port. Nimm nicht <code>127.0.0.1</code> oder <code>localhost</code>, wenn du den Admin von einem anderen Rechner aus öffnest.</p><p>Der Dashboard-Tab im Admin ist nur ein Fenster auf die Adresse unter „URL des ESPHome-Dashboards“. Diese Adresse lädt dein <strong>Browser</strong>, nicht der ioBroker-Rechner. <code>localhost</code> oder <code>127.0.0.1</code> zeigt deshalb auf den Rechner, an dem du gerade sitzt. Läuft dort kein Dashboard, meldet der Browser „localhost verweigert die Verbindung“.</p><h3 id="so-gehst-du-vor" tabindex="-1">So gehst du vor <a class="header-anchor" href="#so-gehst-du-vor" aria-label="Permalink to &quot;So gehst du vor&quot;">​</a></h3><ol><li>Öffne die Instanz-Einstellungen von ESPHome und dort den Reiter „ESPHome-Dashboard“.</li><li>Setze den Haken bei „ESPHome-Dashboard aktivieren“.</li><li>Wähle bei „IP-Adresse, unter der ESPHome Dashboard zur Integration in ioBroker Admin ausgeführt wird“ die IP-Adresse deines ioBroker-Rechners aus der Liste, z. B. <code>192.168.x.y</code>. Schreib <strong>keinen Port</strong> dazu.</li><li>Klapp „Fortschrittlich“ auf. Bei „Port des ESPHome-Dashboards“ steht der Port, Standard ist <code>6052</code>. Ändere ihn nur, wenn der Port schon belegt ist.</li><li>Prüfe im selben Bereich „URL des ESPHome-Dashboards“. Dort muss <code>http://192.168.x.y:6052</code> stehen. Das Feld füllt sich aus IP und Port von selbst.</li><li>Speichere. Die Instanz startet neu und richtet das Dashboard ein. Beim ersten Start dauert das mehrere Minuten, weil Python und ESPHome geladen werden.</li><li>Öffne danach den Tab des ESPHome-Adapters im Admin-Menü links.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Schreib nicht <code>192.168.x.y:6052</code> in das IP-Feld. Der Adapter hängt den Port selbst an, die URL wird dann <code>http://192.168.x.y:6052:6052</code> und der Tab bleibt leer. Das gilt auch für das Beispiel <code>127.0.0.1:6052</code> im README.</p></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Änderst du IP oder Port, nachdem du die URL von Hand angepasst hast, überschreibt der Adapter deine URL wieder mit <code>http://&lt;IP&gt;:&lt;Port&gt;</code>. Bearbeite eine eigene URL deshalb immer zuletzt. Das ist eine bekannte Einschränkung in v1.0.1.</p></div><p>Hast du das Dashboard mit einer Version vor v0.6.1 eingerichtet, die nur IP und Port kannte, übernimmt der Adapter beim ersten Start einmalig <code>http://&lt;IP&gt;:&lt;Port&gt;</code> in das URL-Feld und startet neu. Du musst nichts tun.</p><p>Bleibt der Tab weiter leer, prüfe, ob das Dashboard überhaupt läuft: Im Log der Instanz muss „Starting ESPHome Dashboard“ stehen. Steht dort ein Fehler, hilft <a href="./../fehlerbehebung/dashboard-startet-nicht#dashboard-not-start-pillow-esphome">Warum startet das Dashboard nicht?</a>.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/dashboard-nutzen#show-dashboard-admin-tab-using">Wie zeige ich das Dashboard im Admin-Tab bei HTTPS an?</a></p><p><a id="flash-device-first-time-if"></a></p><h2 id="wie-flashe-ich-ein-gerat-zum-ersten-mal-wenn-der-server-keinen-usb-zugang-hat" tabindex="-1">Wie flashe ich ein Gerät zum ersten Mal, wenn der Server keinen USB-Zugang hat? <a class="header-anchor" href="#wie-flashe-ich-ein-gerat-zum-ersten-mal-wenn-der-server-keinen-usb-zugang-hat" aria-label="Permalink to &quot;Wie flashe ich ein Gerät zum ersten Mal, wenn der Server keinen USB-Zugang hat?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p>',15)])])}const m=t(d,[["render",s]]);export{b as __pageData,m as default};
